// Define pages to scrape from rhythmtraffic.com
const baseUrl = 'https://www.rhythmtraffic.com';

// Add all important pages here
const pages = [
  { url: baseUrl, name: 'Home' },
  { url: `${baseUrl}/about`, name: 'About Us' },
  { url: `${baseUrl}/services`, name: 'Services' },
  { url: `${baseUrl}/solutions`, name: 'Solutions' },
  { url: `${baseUrl}/products`, name: 'Products' },
  { url: `${baseUrl}/contact`, name: 'Contact' },
  { url: `${baseUrl}/faq`, name: 'FAQ' },
  { url: `${baseUrl}/blog`, name: 'Blog' },
  { url: `${baseUrl}/case-studies`, name: 'Case Studies' },
  { url: `${baseUrl}/pricing`, name: 'Pricing' }
];

return pages.map(page => ({
  json: {
    ...page,
    scrapedAt: new Date().toISOString()
  }
}));

// Process and structure the extracted content
const input = $input.first().json;
const pageName = $('Fetch Page').first().json.name || 'Unknown Page';
const pageUrl = $('Fetch Page').first().json.url;

// Combine all text content
let content = '';

// Add title
if (input.title) {
  content += `# ${input.title}\n\n`;
}

// Add meta description
if (input.metaDescription) {
  content += `${input.metaDescription}\n\n`;
}

// Add headings and structure
if (input.h1 && input.h1.length > 0) {
  input.h1.forEach(h => {
    if (h && h.trim()) content += `## ${h.trim()}\n\n`;
  });
}

if (input.h2 && input.h2.length > 0) {
  input.h2.forEach(h => {
    if (h && h.trim()) content += `### ${h.trim()}\n\n`;
  });
}

// Add paragraphs
if (input.paragraphs && input.paragraphs.length > 0) {
  input.paragraphs.forEach(p => {
    if (p && p.trim() && p.trim().length > 20) {
      content += `${p.trim()}\n\n`;
    }
  });
}

// Add list items as bullet points
if (input.listItems && input.listItems.length > 0) {
  const validItems = input.listItems.filter(li => li && li.trim() && li.trim().length > 10);
  if (validItems.length > 0) {
    validItems.forEach(li => {
      content += `- ${li.trim()}\n`;
    });
    content += '\n';
  }
}

// Clean up content
content = content
  .replace(/\n{3,}/g, '\n\n')
  .replace(/\s+/g, ' ')
  .replace(/ \n/g, '\n')
  .trim();

return {
  pageName,
  pageUrl,
  content,
  charCount: content.length,
  wordCount: content.split(/\s+/).length,
  scrapedAt: new Date().toISOString()
};

// Chunk website content for vector storage
const content = $json.content;
const pageName = $json.pageName;
const pageUrl = $json.pageUrl;
const chunkSize = 800;
const chunkOverlap = 150;

const chunks = [];
let startIndex = 0;

while (startIndex < content.length) {
  const endIndex = Math.min(startIndex + chunkSize, content.length);

  let actualEnd = endIndex;
  if (endIndex < content.length) {
    const searchStart = Math.max(endIndex - 80, startIndex);
    const searchText = content.substring(searchStart, endIndex + 40);

    const paragraphBreak = searchText.lastIndexOf('\n\n');
    const sentenceBreak = Math.max(
      searchText.lastIndexOf('. '),
      searchText.lastIndexOf('? '),
      searchText.lastIndexOf('! ')
    );

    if (paragraphBreak > 40) {
      actualEnd = searchStart + paragraphBreak + 2;
    } else if (sentenceBreak > 40) {
      actualEnd = searchStart + sentenceBreak + 2;
    }
  }

  const chunkText = content.substring(startIndex, actualEnd).trim();

  if (chunkText.length > 50) {
    chunks.push({
      pageName,
      pageUrl,
      chunkIndex: chunks.length,
      content: chunkText,
      metadata: {
        source: 'website',
        page: pageName,
        url: pageUrl,
        chunkId: `web_${pageName.toLowerCase().replace(/\s+/g, '_')}_${chunks.length}`,
        createdAt: new Date().toISOString()
      }
    });
  }

  startIndex = actualEnd - chunkOverlap;
}

return chunks;

// Summarize scraping results
const items = $input.all();

return {
  totalChunks: items.length,
  pages: [...new Set(items.map(i => i.json.pageName))],
  completedAt: new Date().toISOString(),
  status: 'success'
};
